import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s)>\]]+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc.split('@')[-1]
        domain = domain.split(':')[0]
        if domain:
            domains.add(domain)
    results = {}
    for domain in domains:
        try:
            params = {'apiKey': API_KEY, 'domain': domain}
            response = requests.get('https://api.ipgeolocation.io/ipgeo', params=params, timeout=10)
            if response.status_code == 200:
                try:
                    data = response.json()
                except ValueError:
                    data = None
            else:
                data = None
        except requests.RequestException:
            data = None
        results[domain] = data
    return results
```

