        return []
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    recipients = []
    if isinstance(data, list):
        recipients = data
    elif isinstance(data, dict):
        if "recipients" in data and isinstance(data["recipients"], list):
            recipients = data["recipients"]
        else:
            recipients = [data]
    emails = []
    names = []
    for r in recipients:
        if not isinstance(r, dict):
            continue
        email = r.get("email")
        name = r.get("name")
        if email and name:
            emails.append(email)
            names.append(name)
    if not emails or not names:
        return []
    subject_line = "Subject: Extracted Names"
    body = "\n".join(names)
    message = subject_line + "\n\n" + body
    close_smtp = False
    client = smtp
    try:
        if client is None:
            client = smtplib.SMTP(smtp_server, smtp_port)
            client.starttls()
            client.login(email_address, email_password)
            close_smtp = True
        client.sendmail(email_address, emails, message)
    finally:
        if close_smtp and client is not None:
            try:
                client.quit()
            except Exception:
                pass
    return names

