1. Iterate through all files in the given directory path.
2. For each file ending with ".json", open and load its content as JSON.
3. Traverse each JSON object recursively to collect all keys encountered (including nested keys).
4. Maintain a counter to track how many times each key appears across all JSON files.
5. Return the counter as a regular dictionary mapping keys to their appearance counts.

### code
```python
import collections
import json
import os
def task_func(directory_path: str) -> dict:
    counter = collections.Counter()

    def collect_keys(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                counter[k] += 1
                collect_keys(v)
        elif isinstance(obj, list):
            for item in obj:
                collect_keys(item)

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            try:
                with open(file_path, 'r') as f:
                    data = json.load(f)
                    collect_keys(data)
            except (json.JSONDecodeError, OSError):
                continue

    return dict(counter)
```

