import json
from glob import glob
def task_func(directory, string):
    def contains_string(obj, target):
        if isinstance(obj, dict):
            for v in obj.values():
                if contains_string(v, target):
                    return True
        elif isinstance(obj, list):
            for item in obj:
                if contains_string(item, target):
                    return True
        elif isinstance(obj, str):
            if obj == target:
                return True
        return False
    pattern = directory.rstrip('/') + '/**/*.json'
    files = glob(pattern, recursive=True)
    result = []
