import json
import re
import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    num_pattern = re.compile(r'^[+-]?\d+(\.\d+)?$')
    normalized = {}
    for k, v in data.items():
        if isinstance(v, (int, float)):
            normalized[k] = float(v) * 2.0
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2.0)
                elif isinstance(item, str) and num_pattern.match(item.strip()):
                    num = float(item.strip())
                    new_list.append(num * 2.0)
                else:
                    new_list.append(item)
            normalized[k] = new_list
        elif isinstance(v, str):
            s = v.strip()
            if num_pattern.match(s):
                num = float(s)
                normalized[k] = num * 2.0
            else:
                normalized[k] = v
        else:
            normalized[k] = v
    try:
        df = pd.DataFrame.from_dict(normalized, orient='index').T
    except ValueError:
        return pd.DataFrame()
    return df
