    for d in data:
        for key, value in d.items():
            stats[key].append(value)
    result = {}
    for k, v in stats.items():
        arr = np.array(v, dtype=float)
        result[k] = {
            "mean": float(np.mean(arr)),
            "median": float(np.median(arr))
        }
    with open(output_file, "w", newline="") as f:
